export type Category = {
  slug: string
  label: string
}

export const categories: Category[] = [
  { slug: 'featured', label: 'Featured products' },
  { slug: 'sale', label: 'Products on sale' },
]

export function getCategoryHeading(slug: string) {
  return categories.find((category) => category.slug === slug)?.label ?? 'Featured products'
}

export type Category = {
  slug: string
  label: string
}

export const categories: Category[] = [
  { slug: 'featured', label: 'Featured products' },
  { slug: 'sale', label: 'Products on sale' },
]

export function getCategoryHeading(slug: string) {
  return categories.find((category) => category.slug === slug)?.label ?? 'Featured products'
}

export type CategoryData = {
  heading: string
  products: string[]
}

const cache = new Map<string, CategoryData>()
const inflight = new Map<string, Promise<CategoryData>>()

export function getCachedCategory(slug: string) {
  return cache.get(slug)
}

export function setCachedCategory(slug: string, data: CategoryData) {
  cache.set(slug, data)
}

export function prefetchCategoryData(
  slug: string,
  loader: () => Promise<CategoryData>,
) {
  if (cache.has(slug)) {
    return
  }

  if (!inflight.has(slug)) {
    inflight.set(
      slug,
      loader().then((data) => {
        cache.set(slug, data)
        inflight.delete(slug)
        return data
      }),
    )
  }
}

export type CategoryData = {
  heading: string
  products: string[]
}

const cache = new Map<string, CategoryData>()
const inflight = new Map<string, Promise<CategoryData>>()

export function getCachedCategory(slug: string) {
  return cache.get(slug)
}

export function setCachedCategory(slug: string, data: CategoryData) {
  cache.set(slug, data)
}

export function prefetchCategoryData(
  slug: string,
  loader: () => Promise<CategoryData>,
) {
  if (cache.has(slug)) {
    return
  }

  if (!inflight.has(slug)) {
    inflight.set(
      slug,
      loader().then((data) => {
        cache.set(slug, data)
        inflight.delete(slug)
        return data
      }),
    )
  }
}

